(() => {
'use strict';
const D=window.UNIVERSE_DATA;
const rows=n=>D[n]?.rows||[];
const BASE={roster:rows('Roster'),titles:rows('Titles & Divisions'),stories:rows('Story Board'),rivalries:rows('Opening Rivalries'),teams:rows('Teams & Factions'),relationships:rows('Relationships'),managers:rows('Managers & Staff'),absences:rows('Absences & Returns'),legends:rows('Legends & Guests'),calendar:rows('PLE Calendar'),shows:rows('Shows')};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const uid=(p='id')=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
const brandClass=s=>/raw/i.test(s)?'raw':/smack/i.test(s)?'smackdown':/nxt/i.test(s)?'nxt':'neutral';
const brandLabel=s=>/smack/i.test(s)?'SMACKDOWN':String(s||'').toUpperCase();
const brand=s=>`<span class="brand-word ${brandClass(s)}">${esc(brandLabel(s))}</span>`;
const pill=(s,c='')=>`<span class="pill ${c}">${esc(s)}</span>`;
const initials=n=>String(n||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const formatDate=iso=>{try{return new Date(iso+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}catch{return iso}};

// Championship-safe picture policy: default images are aggressively head/shoulder cropped.
// Any wrestler can be replaced with your own neutral render from their profile.
const DEFAULT_PHOTO={
'Roman Reigns':'https://s.yimg.com/ny/api/res/1.2/eo9uwU1EzYXySgkrp9fWVg--/YXBwaWQ9aGlnaGxhbmRlcjt3PTk2MDtoPTUzOTtjZj13ZWJw/https%3A/media.zenfs.com/en/wrestling_inc_articles_983/cad090420ce19fc32793158cdc319111',
'Stephanie Vaquer':'https://www.wwe.com/f/styles/talent_champion_xl/public/2025/09/stephanie_Vaquer_Profile.png',
'Cody Rhodes':'https://www.wwe.com/f/styles/talent_champion_lg/public/2025/08/CODY_04262024gd_0100_headSawp_Profile.png',
'Chelsea Green':'https://tjrwrestling.net/app/uploads/2026/08/Chelseacov5-1680x945.jpg',
'Trick Williams':'https://pbs.twimg.com/media/HHqDjVnWoAc4C1L.jpg',
'Sami Zayn':'https://pbs.twimg.com/media/GuDhcqQWAAABphq.jpg'
};

const SAVE_KEY='wweUniverseControlV4';
const blankSave=()=>({
 version:4,
 meta:{name:'My WWE Universe',season:1,seasonLabel:'2026 / 27',startDate:'2026-10-05',currentWeek:1,currentDate:'2026-10-05',createdAt:new Date().toISOString()},
 wrestler:{},titles:{},stories:{},teams:{},relationships:{},absences:{},calendar:{},photos:{},episodes:{},results:{},history:[],customStories:[],customTeams:[],customCalendar:[],customRoster:[]
});
function loadSave(){try{const x=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(x&&x.version===4)return Object.assign(blankSave(),x)}catch{}return blankSave()}
let save=loadSave();
function persist(){localStorage.setItem(SAVE_KEY,JSON.stringify(save));}
function log(type,title,detail=''){save.history.unshift({id:uid('hist'),at:new Date().toISOString(),type,title,detail,season:save.meta.season,week:save.meta.currentWeek});save.history=save.history.slice(0,1000);persist();}
function weekKey(show,week=save.meta.currentWeek,season=save.meta.season){return `S${season}-W${week}-${show}`}
function weekDate(week=save.meta.currentWeek){const d=new Date(save.meta.startDate+'T12:00:00');d.setDate(d.getDate()+(week-1)*7);return d.toISOString().slice(0,10)}
function rosterNow(){return [...BASE.roster.map(r=>({...r,...(save.wrestler[r._id]||{})})),...save.customRoster.map(r=>({...r,...(save.wrestler[r._id]||{})}))]}
function titleNow(r){return {...r,...(save.titles[r._id]||{})}}
function storyNow(r){return {...r,...(save.stories[r._id]||{})}}
function currentChampion(r){return titleNow(r).Champion||r['Starting champion(s)']}
function currentStories(){return [...BASE.stories.map(storyNow),...save.customStories]}
function currentTeams(){return [...BASE.teams.map(r=>({...r,...(save.teams[r._id]||{})})),...save.customTeams]}
function currentCalendar(){return [...BASE.calendar.map(r=>({...r,...(save.calendar[r._id]||{})})),...save.customCalendar]}
function currentAbsence(r){return {...r,...(save.absences[r._id]||{})}}
function personByName(name){return rosterNow().find(r=>r.Name===name)}
function photoFor(name){return save.photos[name]?.src||DEFAULT_PHOTO[name]||''}
function img(name,hero=false){const src=photoFor(name);return src?`<img class="safe-crop" src="${esc(src)}" alt="${esc(name)}" loading="${hero?'eager':'lazy'}" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"/><div class="initials" style="display:none">${esc(initials(name))}</div>`:`<div class="initials">${esc(initials(name))}</div>`}

const icons={overview:'⌂',shows:'▶',roster:'◎',champions:'♛',stories:'ϟ',calendar:'▣',teams:'◈',returns:'↻',results:'✓',manage:'◫',setup:'⚙'};
const labels={overview:'Overview',shows:'Shows & Match Cards',roster:'Superstars',champions:'Championships',stories:'Storylines',calendar:'PLE Calendar',teams:'Teams & Relationships',returns:'Injuries & Returns',results:'History & Results',manage:'My Universe',setup:'Setup Reference',credits:'Snapshot & Credits'};
const nav=['overview','shows','roster','champions','stories','calendar','teams','returns','results','manage','setup'];
let state={route:(location.hash.slice(1)||'overview').split('?')[0],brand:'All brands',query:'',show:'Raw',storyView:'Active stories',teamView:'Teams & Factions',returnView:'Absences & Returns',setupView:'Start Here'};

function pageHead(eyebrow,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function tabs(items,val,attr='tab'){return `<div class="brand-tabs">${items.map(x=>`<button class="tab ${brandClass(x)} ${x===val?'active':''}" data-${attr}="${esc(x)}">${esc(x)}</button>`).join('')}</div>`}
function searchbox(ph='Search…'){return `<label class="searchbox">⌕<input id="filterQuery" value="${esc(state.query)}" placeholder="${esc(ph)}"/></label>`}
function sectionTitle(title,route,label='View all'){return `<div class="section-title"><h2>${title}</h2>${route?`<button data-route="${route}">${label} ↗</button>`:''}</div>`}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),2200)}
function openDrawer(){$('#drawer').classList.add('open');$('#scrim').classList.add('open');$('#drawer').setAttribute('aria-hidden','false')}
function closeDrawer(){$('#drawer').classList.remove('open');$('#scrim').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true')}
function openModal(html){$('#modalBody').innerHTML=html;$('#modalWrap').classList.add('open');$('#modalWrap').setAttribute('aria-hidden','false')}
function closeModal(){$('#modalWrap').classList.remove('open');$('#modalWrap').setAttribute('aria-hidden','true')}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#scrim').classList.remove('nav-open')}
function openSidebar(){$('#sidebar').classList.add('open');$('#scrim').classList.add('nav-open')}
function route(id){state.route=id;location.hash=id;state.query='';render();closeSidebar()}
function navRender(){
 $('#nav').innerHTML=nav.map(id=>`<button class="nav-item ${state.route===id?'active':''}" data-route="${id}"><span>${icons[id]}</span><span>${labels[id]}</span></button>`).join('');
 $('.season-pill').innerHTML=`SEASON ${String(save.meta.season).padStart(2,'0')} <span>${esc(save.meta.seasonLabel)}</span>`;
 $('footer p').textContent=`Season ${String(save.meta.season).padStart(2,'0')} · Week ${save.meta.currentWeek} · Your stories. Your results.`;
}
function render(){navRender();$('#crumb').textContent=labels[state.route]||'Overview';$('#main').innerHTML=(views[state.route]||views.overview)();bindView();window.scrollTo({top:0,behavior:'instant'})}

function overview(){
 const r=rosterNow(),activeStories=currentStories().filter(x=>(x.Status||'Active')!=='Concluded').slice(0,6),results=Object.values(save.results).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at))).slice(0,5);
 const featured=BASE.titles.find(t=>t.Championship==='World Heavyweight')||BASE.titles[0];
 const c=currentChampion(featured);
 return `${pageHead('YOUR LIVING UNIVERSE','Universe overview',`${esc(save.meta.seasonLabel)} · Week ${save.meta.currentWeek} · ${formatDate(weekDate())}`,`<button class="btn primary" data-route="shows">Enter this week’s cards →</button>`)}
 <div class="live-banner"><div><span class="live-dot"></span><b>STARTING SNAPSHOT → YOUR SAVE</b><p>The October 2026 setup is the baseline. Everything after that is yours to update from what WWE 2K26 actually books.</p></div><button class="btn" data-route="manage">Manage save</button></div>
 <div class="overview-feature"><div class="featured-story"><div class="feature-copy"><div class="feature-label">${brand(featured.Brand)}<span>${esc(featured.Championship)}</span></div><div class="eyebrow gold">CURRENT CHAMPIONSHIP PICTURE</div><h2>${esc(c.toUpperCase())}<br/><span>SETS THE PACE.</span></h2><p>Starting champion and challengers are the baseline. Change them whenever your watched Universe changes them.</p><button class="text-link" data-route="champions">Open championship board ↗</button></div><div class="faceoff solo-face">${img(c.split(/ \+ | & /)[0],true)}</div><span class="feature-bottom">SEASON ${String(save.meta.season).padStart(2,'0')} <span>WEEK ${save.meta.currentWeek} · ${formatDate(weekDate())}</span></span></div>
 <div class="on-deck"><div class="eyebrow">THIS WEEK</div><h2>Let 2K book it.</h2><p class="muted">Enter each card after Universe generates it.</p>${['Raw','NXT','SmackDown'].map((b,i)=>{const ep=save.episodes[weekKey(b)];return `<button class="show-shortcut ${brandClass(b)}" data-showlink="${b}"><div><small>${['MONDAY','TUESDAY','FRIDAY'][i]}</small>${brand(b)}</div><span>${ep?.items?.length||0} booked <b>›</b></span></button>`}).join('')}<div class="viewing-rule"><span>◉</span><span>AI vs AI. No protected finishes.<br/>Record what you actually see.</span></div></div></div>
 <div class="stats-strip">${[[r.length,'Superstars','roster'],[BASE.titles.length,'Championships','champions'],[currentStories().length,'Story programs','stories'],[Object.keys(save.results).length,'Results saved','results']].map(([n,l,h])=>`<button data-route="${h}"><strong>${esc(n)}</strong><span>${esc(l)}</span><b>↗</b></button>`).join('')}</div>
 ${sectionTitle('Championship picture','champions','All divisions')}<div class="champ-grid">${BASE.titles.slice(0,6).map(champCard).join('')}</div>
 <div class="overview-lower"><div>${sectionTitle('Stories in motion','stories')} ${activeStories.map(s=>`<article class="rivalry-row" data-story="${esc(s._id)}"><span class="brand-bar ${brandClass(s.Show)}"></span><div><small>${esc(s.Show)} · ${esc(s.Role||'Program')}</small><h3>${esc(s.Program)}</h3></div>${pill(s.Status||'Active',(s.Status||'Active')==='Active'?'active':'')}<b>›</b></article>`).join('')}</div><div>${sectionTitle('Latest history','results','Full history')}${results.length?results.map(x=>`<div class="history-mini"><small>${esc(x.show||'Universe')} · ${esc(x.weekLabel||'')}</small><b>${esc(x.winner||x.title||'Update')}</b><p>${esc(x.finish||x.detail||'')}</p></div>`).join(''):`<div class="note">No results yet. Your first watched match will start the history.</div>`}</div></div>`;
}
function champCard(t){const c=currentChampion(t),first=c.split(/ \+ | & /)[0];return `<article class="champ-card ${brandClass(t.Brand)}" data-title="${t._id}"><div class="brand-strip ${brandClass(t.Brand)}"></div><div class="photo">${img(first)}</div><div class="body"><small>${esc(t.Championship)}</small><h3>${esc(c)}</h3><p>${brand(t.Brand)}</p><span class="more">Open division ↗</span></div></article>`}

function rosterView(){const r=rosterNow();const filtered=r.filter(x=>(state.brand==='All brands'||x['Home brand']===state.brand)&&Object.values(x).join(' ').toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>Number(!!photoFor(b.Name))-Number(!!photoFor(a.Name))||a.Name.localeCompare(b.Name));return `${pageHead('THE FULL ROSTER','Superstars','The starting roster, now editable as your save changes.',`<button class="btn" id="addSuperstar">+ Add custom superstar</button>`)}${tabs(['All brands','Raw','SmackDown','NXT','Evolve','Guest reserve'],state.brand,'brand')}<div class="filters">${searchbox('Search superstar, team, or division…')}<span class="count">${filtered.length} entries</span></div><div class="roster-grid">${filtered.map(x=>`<article class="super-card ${brandClass(x['Home brand'])}" data-person="${esc(x.Name)}"><div class="photo">${img(x.Name)}</div><div class="body"><div class="meta">${brand(x['Home brand'])}<span>${esc(x.Alignment)}</span></div><h3>${esc(x.Name)}</h3><p>${esc(x['Primary title lane']||x.Group||'Roster')}</p>${pill(x['Starting status']||'Active',(x['Starting status']||'Active')==='Active'?'active':'')}</div></article>`).join('')}</div>`}

function person(name){const r=personByName(name);if(!r)return;const ties=BASE.relationships.filter(x=>x['Person A']===name||x['Person B']===name);$('#drawerBody').innerHTML=`<div class="drawer-hero">${img(name)}</div><div class="drawer-pad"><div class="drawer-actions"><button class="btn primary" data-edit-person="${esc(name)}">Edit superstar</button><button class="btn" data-photo-person="${esc(name)}">Change photo</button></div><div class="eyebrow">${esc(r['Home brand'])} · ${esc(r.Alignment)}</div><h2>${esc(name)}</h2>${[['Status',r['Starting status']],['Title lane',r['Primary title lane']],['Team / faction',r['Team / faction']],['Manager',r.Manager],['2K26 access',r['2K26 access']],['Universe notes',r['Setup / character notes']]].filter(x=>x[1]).map(([k,v])=>`<div class="detail-row"><h4>${esc(k)}</h4><p>${esc(v)}</p></div>`).join('')}${ties.length?`<div class="detail-row"><h4>Connections</h4>${ties.map(t=>`<p style="margin:8px 0"><b>${esc(t['Person A']===name?t['Person B']:t['Person A'])}</b> · ${esc(t.Tie)} · ${esc(t['Game setting'])}</p>`).join('')}</div>`:''}<div class="detail-row"><h4>Photo policy</h4><p>Use a neutral render or head-and-shoulders shot. Avoid any championship that is not part of this save’s current title state.</p></div></div>`;openDrawer();setTimeout(()=>{const ep=$('[data-edit-person]');if(ep)ep.onclick=()=>editPerson(name);const pp=$('[data-photo-person]');if(pp)pp.onclick=()=>editPhoto(name)},0)}
function editPerson(name){const r=personByName(name);if(!r)return;openModal(`<div class="eyebrow">EDIT SUPERSTAR</div><h2 id="modalTitle">${esc(name)}</h2><p>Change only what your Universe has actually changed.</p><form class="form" id="personForm"><div class="row"><label>Brand<select name="brand">${['Raw','SmackDown','NXT','Evolve','Guest reserve','Legends'].map(v=>`<option ${r['Home brand']===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Alignment<select name="alignment">${['Face','Heel','Tweener'].map(v=>`<option ${r.Alignment===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="row"><label>Status<input name="status" value="${esc(r['Starting status']||'Active')}"/></label><label>Primary title lane<input name="lane" value="${esc(r['Primary title lane']||'')}"/></label></div><div class="row"><label>Team / faction<input name="team" value="${esc(r['Team / faction']||'')}"/></label><label>Manager<input name="manager" value="${esc(r.Manager||'')}"/></label></div><label>Universe notes<textarea name="notes">${esc(r['Setup / character notes']||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelEdit">Cancel</button><button type="submit" class="btn primary">Save changes</button></div></form>`);$('#cancelEdit').onclick=closeModal;$('#personForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),base=BASE.roster.find(x=>x.Name===name);save.wrestler[r._id]={'Home brand':f.get('brand'),Alignment:f.get('alignment'),'Starting status':f.get('status'),'Primary title lane':f.get('lane'),'Team / faction':f.get('team'),Manager:f.get('manager'),'Setup / character notes':f.get('notes')};persist();log('Roster',name,`Updated roster profile: ${f.get('brand')} · ${f.get('status')}`);closeModal();closeDrawer();toast('Superstar updated.');render()}}
function addSuperstar(){openModal(`<div class="eyebrow">NEW SUPERSTAR</div><h2 id="modalTitle">Add someone to your Universe</h2><form class="form" id="newPersonForm"><label>Name<input name="name" required></label><div class="row"><label>Brand<select name="brand"><option>Raw</option><option>SmackDown</option><option>NXT</option><option>Evolve</option><option>Guest reserve</option></select></label><label>Alignment<select name="alignment"><option>Face</option><option>Heel</option><option>Tweener</option></select></label></div><div class="row"><label>Status<input name="status" value="Active"></label><label>Title lane<input name="lane"></label></div><label>Team / faction<input name="team"></label><label>Notes<textarea name="notes"></textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelNewPerson">Cancel</button><button class="btn primary">Add superstar</button></div></form>`);$('#cancelNewPerson').onclick=closeModal;$('#newPersonForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')).trim();if(rosterNow().some(x=>x.Name.toLowerCase()===name.toLowerCase())){toast('That superstar is already in the roster.');return}const r={_id:uid('custom-roster'),Name:name,'Home brand':f.get('brand'),Group:'Custom',Role:'Wrestler',Alignment:f.get('alignment'),'Starting status':f.get('status'),'Primary title lane':f.get('lane'),'Team / faction':f.get('team'),Manager:'','2K26 access':'Custom / added during save','Setup / character notes':f.get('notes'),Source:'User-added'};save.customRoster.push(r);persist();log('Roster',name,'Added to the Universe roster.');closeModal();toast('Superstar added.');render()}}
function editPhoto(name){openModal(`<div class="eyebrow">CHAMPIONSHIP-SAFE PHOTO</div><h2 id="modalTitle">${esc(name)}</h2><p>Choose a neutral render or headshot. The site crops low on the body so belts are less likely to appear.</p><form class="form" id="photoForm"><label>Image URL<input name="url" value="${esc(save.photos[name]?.src||'')}" placeholder="https://…"></label><label>Or upload an image<input type="file" id="photoFile" accept="image/*"></label><div class="photo-guideline"><b>Best:</b> front-facing render, entrance portrait, or head-and-shoulders photo with no championship visible.</div><div class="form-actions"><button type="button" class="btn danger" id="removePhoto">Use default</button><button type="button" class="btn" id="cancelPhoto">Cancel</button><button class="btn primary" type="submit">Save photo</button></div></form>`);$('#cancelPhoto').onclick=closeModal;$('#removePhoto').onclick=()=>{delete save.photos[name];persist();closeModal();closeDrawer();toast('Custom photo removed.');render()};$('#photoForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),file=$('#photoFile').files[0];let src=String(f.get('url')||'').trim();if(file)src=await compressImage(file);if(!src){toast('Add a URL or choose an image.');return}save.photos[name]={src,updatedAt:new Date().toISOString()};persist();log('Photo',name,'Updated profile photo.');closeModal();closeDrawer();toast('Photo updated.');render()}}
function compressImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const im=new Image();im.onload=()=>{const size=700,c=document.createElement('canvas');c.width=size;c.height=size;const ctx=c.getContext('2d'),scale=Math.max(size/im.width,size/im.height),w=im.width*scale,h=im.height*scale;ctx.drawImage(im,(size-w)/2,(size-h)*.18,w,h);resolve(c.toDataURL('image/jpeg',.78))};im.onerror=reject;im.src=reader.result};reader.readAsDataURL(file)})}

function champions(){const filtered=BASE.titles.filter(t=>state.brand==='All brands'||t.Brand.includes(state.brand));return `${pageHead('THE GOLD STANDARD','Championships & divisions','Starting champions are the baseline. Edit the champion whenever your save changes the title.',`<button class="btn" data-route="results">View title history</button>`)}${tabs(['All brands','Raw','SmackDown','NXT'],state.brand,'brand')}<div class="division-grid">${filtered.map(t=>{const x=titleNow(t),c=currentChampion(t),first=c.split(/ \+ | & /)[0];return `<article class="division-card ${brandClass(t.Brand)}"><div class="division-head">${brand(t.Brand)}<span>♛</span></div><div class="division-champion"><div class="photo">${img(first)}</div><div><small>${esc(t.Championship)}</small><h2>${esc(c)}</h2>${pill('Current champion','gold')}</div></div><div class="division-contenders"><h4>ELIGIBLE DIVISION</h4><div>${esc(x['Active primary members']||t['Active primary members']).split(', ').map(n=>`<button data-person="${esc(n)}">${esc(n)}</button>`).join('')}</div></div><div class="card-actions"><button class="btn" data-title="${t._id}">Division details</button><button class="btn primary" data-change-title="${t._id}">Change champion</button></div></article>`}).join('')}</div>`}
function titleDetail(id){const t=BASE.titles.find(x=>x._id===id);if(!t)return;const x=titleNow(t);$('#drawerBody').innerHTML=`<div class="drawer-pad"><div class="eyebrow">${esc(t.Brand)} · CHAMPIONSHIP</div><h2>${esc(t.Championship)}</h2><div class="detail-row"><h4>Current champion</h4><p>${esc(currentChampion(t))}</p></div><div class="detail-row"><h4>Starting champion</h4><p>${esc(t['Starting champion(s)'])}</p></div><div class="detail-row"><h4>Eligible division</h4><p>${esc(x['Active primary members'])}</p></div><div class="detail-row"><h4>Secondary / return lanes</h4><p>${esc(x['Secondary / pairs / return lanes'])}</p></div><button class="btn primary full" data-change-title="${id}">Change champion</button></div>`;openDrawer();setTimeout(()=>{$('[data-change-title]')?.addEventListener('click',()=>changeChampion(id))},0)}
function changeChampion(id){const t=BASE.titles.find(x=>x._id===id),current=currentChampion(t);openModal(`<div class="eyebrow">TITLE UPDATE</div><h2 id="modalTitle">${esc(t.Championship)}</h2><p>Use this after a title change, vacancy, reinstatement, or manual correction.</p><form class="form" id="titleForm"><label>Champion(s)<input name="champ" value="${esc(current)}" required></label><label>Reason / event<input name="reason" placeholder="e.g. Won on Raw, vacated due to injury"></label><div class="form-actions"><button type="button" class="btn" id="cancelTitle">Cancel</button><button class="btn primary">Save title state</button></div></form>`);$('#cancelTitle').onclick=closeModal;$('#titleForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),champ=String(f.get('champ')).trim(),reason=String(f.get('reason')||'Manual title update');save.titles[id]={...(save.titles[id]||{}),Champion:champ};persist();log('Championship',t.Championship,`${current} → ${champ}. ${reason}`);closeModal();closeDrawer();toast('Championship updated.');render()}}

function storiesView(){const all=currentStories(),filtered=all.filter(s=>(state.brand==='All brands'||s.Show===state.brand)&&Object.values(s).join(' ').toLowerCase().includes(state.query.toLowerCase())&&(state.storyView==='All stories'||(s.Status||'Active')===state.storyView.replace(' stories','')));return `${pageHead('EVERY STORY HAS STAKES','Storylines','Start from the opening context, then update the story after what actually happens.',`<button class="btn primary" id="addStory">+ New story</button>`)}${tabs(['All brands','Raw','SmackDown','NXT'],state.brand,'brand')}<div class="filters">${searchbox('Find a rivalry, superstar, or title…')}<select id="storyView"><option ${state.storyView==='Active stories'?'selected':''}>Active stories</option><option ${state.storyView==='Paused stories'?'selected':''}>Paused stories</option><option ${state.storyView==='Concluded stories'?'selected':''}>Concluded stories</option><option ${state.storyView==='All stories'?'selected':''}>All stories</option></select><span class="count">${filtered.length} programs</span></div><div class="story-grid">${filtered.map((s,i)=>`<article class="story-card ${brandClass(s.Show)}" data-story="${esc(s._id)}"><div class="top">${brand(s.Show)}<span>${String(i+1).padStart(2,'0')}</span></div><div class="body"><small>${esc(s.Role||'Season program')} · ${esc(s.Status||'Active')}</small><h3>${esc(s.Program)}</h3><p>${esc(s['Current notes']||s['Starting situation']||s.Goals||'')}</p><div class="foot">Open & update story ↗</div></div></article>`).join('')}</div>`}
function storyDetail(id){const s=currentStories().find(x=>x._id===id);if(!s)return;$('#drawerBody').innerHTML=`<div class="drawer-pad"><div class="drawer-actions"><button class="btn primary" data-edit-story="${id}">Update story</button></div><div class="eyebrow">${esc(s.Show)} · ${esc(s.Status||'Active')}</div><h2>${esc(s.Program)}</h2>${[['Goals',s.Goals],['Starting situation',s['Starting situation']],['Current notes',s['Current notes']],['Next decision',s['Next decision']],['If momentum grows',s['If momentum grows']],['If momentum stalls',s['If momentum stalls / reverses']]].filter(x=>x[1]).map(([k,v])=>`<div class="detail-row"><h4>${esc(k)}</h4><p>${esc(v)}</p></div>`).join('')}</div>`;openDrawer();setTimeout(()=>{$('[data-edit-story]')?.addEventListener('click',()=>editStory(id))},0)}
function editStory(id){const s=currentStories().find(x=>x._id===id),isBase=BASE.stories.some(x=>x._id===id);openModal(`<div class="eyebrow">STORY UPDATE</div><h2 id="modalTitle">${esc(s.Program)}</h2><form class="form" id="storyForm"><div class="row"><label>Status<select name="status">${['Active','Paused','Concluded'].map(v=>`<option ${(s.Status||'Active')===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Brand<select name="show">${['Raw','SmackDown','NXT','Cross-brand'].map(v=>`<option ${s.Show===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Current notes<textarea name="notes" placeholder="What has actually happened so far?">${esc(s['Current notes']||'')}</textarea></label><label>Next decision<textarea name="next">${esc(s['Next decision']||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelStory">Cancel</button><button class="btn primary">Save story</button></div></form>`);$('#cancelStory').onclick=closeModal;$('#storyForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),changes={Status:f.get('status'),Show:f.get('show'),'Current notes':f.get('notes'),'Next decision':f.get('next')};if(isBase)save.stories[id]={...(save.stories[id]||{}),...changes};else Object.assign(save.customStories.find(x=>x._id===id),changes);persist();log('Story',s.Program,`Status: ${changes.Status}. ${changes['Current notes']||''}`);closeModal();closeDrawer();toast('Story updated.');render()}}
function addStory(){openModal(`<div class="eyebrow">NEW STORY</div><h2 id="modalTitle">Add a Universe program</h2><form class="form" id="newStoryForm"><label>Story / rivalry name<input name="program" required placeholder="e.g. Chad Gable / Penta"></label><div class="row"><label>Brand<select name="show"><option>Raw</option><option>SmackDown</option><option>NXT</option><option>Cross-brand</option></select></label><label>Role<input name="role" placeholder="Title program, personal feud…"></label></div><label>Goal<textarea name="goals"></textarea></label><label>Starting / current situation<textarea name="notes"></textarea></label><label>Next decision<textarea name="next"></textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelNewStory">Cancel</button><button class="btn primary">Add story</button></div></form>`);$('#cancelNewStory').onclick=closeModal;$('#newStoryForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const s={_id:uid('story'),Program:f.get('program'),Show:f.get('show'),Role:f.get('role'),Goals:f.get('goals'),'Starting situation':f.get('notes'),'Current notes':f.get('notes'),'Next decision':f.get('next'),Status:'Active'};save.customStories.push(s);persist();log('Story',s.Program,'New story added.');closeModal();toast('Story added.');render()}}

function showsView(){const show=state.show,ep=save.episodes[weekKey(show)]||{items:[]};return `${pageHead('LET 2K BOOK THE SHOW','Shows & match cards','This page begins empty. Add the matches and segments your game actually generates.',`<div class="head-actions"><button class="btn" id="prevWeek">← Week</button><button class="btn" id="nextWeek">Week →</button></div>`)}<div class="week-control"><div><div class="eyebrow">SEASON ${String(save.meta.season).padStart(2,'0')} · WEEK ${save.meta.currentWeek}</div><h2>${formatDate(weekDate())}</h2></div><div>${tabs(['Raw','NXT','SmackDown'],show,'show')}</div></div><div class="episode-header ${brandClass(show)}"><div><small>GAME-BOOKED CARD</small>${brand(show)}</div><div><strong>${ep.items.length}</strong><span>items entered</span></div></div><div class="empty-card-tools"><button class="btn primary" id="addMatch">+ Add match</button><button class="btn" id="addSegment">+ Add segment</button><button class="btn" id="copyCard">Copy card text</button></div>${ep.items.length?`<div class="match-card-list">${ep.items.sort((a,b)=>a.order-b.order).map((m,i)=>m.type==='segment'?`<article class="segment-line"><span>SEGMENT</span><div><h3>${esc(m.text)}</h3><p>${esc(m.notes||'')}</p></div><button class="text-link" data-edit-item="${m.id}">Edit</button></article>`:`<article class="match-card ${m.result?'completed':''}"><span class="match-number">${String(i+1).padStart(2,'0')}</span><div class="match-main"><div class="match-label"><span>${m.mainEvent?'MAIN EVENT':'MATCH'}</span>${m.stakes?pill(m.stakes):''}</div><h2>${esc(m.text)}</h2>${m.notes?`<p>${esc(m.notes)}</p>`:''}${m.result?`<div class="recorded-line">✓ ${esc(m.result.winner)} · ${esc(m.result.finish)}</div>`:''}</div><div class="card-side-actions"><button class="btn ${m.result?'':'primary'}" data-record-live="${m.id}">${m.result?'Edit result':'Record result'}</button><button class="text-link" data-edit-item="${m.id}">Edit card</button></div></article>`).join('')}</div>`:`<div class="empty"><div style="font-size:42px">▶</div><h3>${esc(show)} is waiting on the game.</h3><p>Open Universe Mode, see what 2K booked, then add the card here. Nothing is predetermined.</p><button class="btn primary" id="emptyAddMatch">+ Add first match</button></div>`}<div class="note">The old four-week planned cards remain only in the original workbook as reference. They are not loaded into your active Universe timeline.</div>`}
function addCardItem(type='match',existing=null){const show=state.show;openModal(`<div class="eyebrow">${esc(show)} · WEEK ${save.meta.currentWeek}</div><h2 id="modalTitle">${existing?'Edit':'Add'} ${type}</h2><form class="form" id="cardForm"><label>${type==='match'?'Match':'Segment'}<input name="text" value="${esc(existing?.text||'')}" required placeholder="${type==='match'?'Wrestler vs Wrestler':'Promo / confrontation / backstage scene'}"></label>${type==='match'?`<div class="row"><label>Stakes<input name="stakes" value="${esc(existing?.stakes||'')}" placeholder="Non-title, qualifier, title…"></label><label>Main event<select name="main"><option value="no" ${!existing?.mainEvent?'selected':''}>No</option><option value="yes" ${existing?.mainEvent?'selected':''}>Yes</option></select></label></div>`:''}<label>Notes<textarea name="notes">${esc(existing?.notes||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelCard">Cancel</button>${existing?'<button type="button" class="btn danger" id="deleteCard">Delete</button>':''}<button class="btn primary">Save to card</button></div></form>`);$('#cancelCard').onclick=closeModal;if(existing)$('#deleteCard').onclick=()=>{const ep=save.episodes[weekKey(show)];ep.items=ep.items.filter(x=>x.id!==existing.id);persist();log('Show',show,`Removed ${existing.text} from Week ${save.meta.currentWeek}.`);closeModal();toast('Card item removed.');render()};$('#cardForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),ep=save.episodes[weekKey(show)]||{items:[]},item=existing||{id:uid('item'),type,order:ep.items.length+1};item.text=f.get('text');item.notes=f.get('notes');if(type==='match'){item.stakes=f.get('stakes');item.mainEvent=f.get('main')==='yes'}if(!existing)ep.items.push(item);save.episodes[weekKey(show)]=ep;persist();log('Show',show,`${existing?'Updated':'Added'} ${item.text} on Week ${save.meta.currentWeek}.`);closeModal();toast('Card updated.');render()}}
function recordLiveResult(itemId){const ep=save.episodes[weekKey(state.show)],m=ep?.items.find(x=>x.id===itemId);if(!m)return;const p=m.result||{};openModal(`<div class="eyebrow">${esc(state.show)} · WEEK ${save.meta.currentWeek}</div><h2 id="modalTitle">${p.winner?'Edit result':'Record observed result'}</h2><p>Record what the AI match actually produced.</p><form class="form" id="resultForm"><label>Actual match<input name="match" value="${esc(m.text)}" required></label><div class="row"><label>Winner / winning team<input name="winner" value="${esc(p.winner||'')}" required></label><label>Finish<select name="finish">${['Pinfall','Submission','Disqualification','Count-out','Ladder retrieval','Escape','Last standing','Draw','No contest','Other'].map(x=>`<option ${p.finish===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Championship involved<select name="title"><option value="">No championship update</option>${BASE.titles.map(t=>`<option value="${t._id}" ${p.title===t._id?'selected':''}>${esc(t.Brand)} · ${esc(t.Championship)}</option>`).join('')}</select></label><label>Champion(s) after match<input name="champion" value="${esc(p.champion||'')}" placeholder="Only needed if a championship was involved"></label><label>What changed because of this match?<textarea name="notes" placeholder="Interference, injury, earned shot, rivalry beat…">${esc(p.notes||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelResult">Cancel</button><button class="btn primary">Save result</button></div></form>`);$('#cancelResult').onclick=closeModal;$('#resultForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),result={id:uid('res'),match_text:f.get('match'),winner:f.get('winner'),finish:f.get('finish'),title:f.get('title'),champion:f.get('champion'),notes:f.get('notes'),show:state.show,season:save.meta.season,week:save.meta.currentWeek,weekLabel:`S${save.meta.season} W${save.meta.currentWeek}`,date:weekDate(),updated_at:new Date().toISOString()};m.text=result.match_text;m.result=result;save.results[result.id]=result;if(result.title&&result.champion){const t=BASE.titles.find(x=>x._id===result.title),old=currentChampion(t);save.titles[result.title]={...(save.titles[result.title]||{}),Champion:result.champion};log('Championship',t.Championship,`${old} → ${result.champion} after ${result.match_text}.`)}log('Result',result.match_text,`${result.winner} · ${result.finish}. ${result.notes||''}`);persist();closeModal();toast('Result saved.');render()}}

function calendarView(){const data=currentCalendar(),months=[...new Set(data.map(r=>r.Month))];return `${pageHead('THE ROAD THROUGH THE SEASONS','PLE calendar','Season-one starting calendar. Edit, add, or move events as your Universe develops.',`<button class="btn primary" id="addPLE">+ Add event</button>`)}<div class="calendar">${months.map(m=>{const es=data.filter(r=>r.Month===m),[mn,yr]=m.split(' ');return `<section class="month"><h2>${esc(mn)}<small>${esc(yr||'')}</small></h2><div>${es.map(e=>`<article class="event-card"><div class="event-date">▣ <b>${esc(e['Game slot / date']||'TBD')}</b></div><div class="event-body"><div>${pill(e.Shows||'All brands',e.Shows==='NXT'?'gold':'')} <span style="font-size:10px;color:#8490a2;margin-left:7px">${esc(e.Matches||'')} matches</span></div><h3>${esc(e.Event)}</h3><p>${esc(e['Card formula / note']||'')}</p><small style="display:block;color:#768296;margin-top:9px">${esc(e['Date status']||'Universe date')}</small></div><button class="text-link" data-edit-ple="${e._id}">Edit ↗</button></article>`).join('')}</div></section>`}).join('')}</div>`}
function editPLE(id=null){const e=currentCalendar().find(x=>x._id===id)||{_id:uid('ple'),Month:'',Event:'',Shows:'Raw + SD',Matches:'6','Game slot / date':'','Date status':'Universe date','Card formula / note':''};const isBase=BASE.calendar.some(x=>x._id===e._id);openModal(`<div class="eyebrow">PLE CALENDAR</div><h2 id="modalTitle">${id?'Edit event':'Add event'}</h2><form class="form" id="pleForm"><div class="row"><label>Month<input name="month" value="${esc(e.Month)}" placeholder="Oct 2026" required></label><label>Slot / date<input name="date" value="${esc(e['Game slot / date'])}"></label></div><label>Event<input name="event" value="${esc(e.Event)}" required></label><div class="row"><label>Shows<input name="shows" value="${esc(e.Shows)}"></label><label>Match count<input name="matches" value="${esc(e.Matches)}"></label></div><label>Notes<textarea name="notes">${esc(e['Card formula / note'])}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelPle">Cancel</button><button class="btn primary">Save event</button></div></form>`);$('#cancelPle').onclick=closeModal;$('#pleForm').onsubmit=x=>{x.preventDefault();const f=new FormData(x.currentTarget),changes={Month:f.get('month'),'Game slot / date':f.get('date'),Event:f.get('event'),Shows:f.get('shows'),Matches:f.get('matches'),'Card formula / note':f.get('notes')};if(isBase)save.calendar[e._id]={...(save.calendar[e._id]||{}),...changes};else{Object.assign(e,changes);if(!id)save.customCalendar.push(e)}persist();log('Calendar',changes.Event,`${changes.Month} · ${changes['Game slot / date']}`);closeModal();toast('Calendar updated.');render()}}

function teamsView(){const sheet=state.teamView,data=sheet==='Teams & Factions'?currentTeams():sheet==='Relationships'?BASE.relationships:BASE.managers;const filtered=data.filter(r=>Object.values(r).join(' ').toLowerCase().includes(state.query.toLowerCase()));return `${pageHead('WHO STANDS WITH WHOM','Teams & relationships','Starting connections that you can update as turns, alliances, splits, and reunions happen.',sheet==='Teams & Factions'?`<button class="btn primary" id="addTeam">+ New team / faction</button>`:'')}${tabs(['Teams & Factions','Relationships','Managers & Staff'],state.teamView,'teamview')}<div class="filters">${searchbox('Search a team or superstar…')}<span class="count">${filtered.length} entries</span></div><div class="reference-grid">${filtered.map(r=>sheet==='Teams & Factions'?`<article class="info-card" data-team="${r._id}"><div class="body"><small>${esc(r.Brand)} · ${esc(r.Kind)}</small><h3>${esc(r.Name)}</h3><p>${esc(r.Members)}</p><span class="more">Open team ↗</span></div></article>`:sheet==='Relationships'?`<article class="info-card"><div class="body">${pill(r.Tie,/enemy|conflict|tension|feud/i.test(r.Tie)?'hot':'')}<h3 style="margin-top:18px">${esc(r['Person A'])} & ${esc(r['Person B'])}</h3><p>${esc(r['Game setting'])}</p></div></article>`:`<article class="info-card"><div class="body"><small>${esc(r.Show)}</small><h3>${esc(r.Person)}</h3><p>${esc(r.Role)} · ${esc(r.Assignment)}</p></div></article>`).join('')}</div>`}
function teamDetail(id){const t=currentTeams().find(x=>x._id===id);if(!t)return;$('#drawerBody').innerHTML=`<div class="drawer-pad"><div class="drawer-actions"><button class="btn primary" data-edit-team="${id}">Edit team</button></div><div class="eyebrow">${esc(t.Brand)} · ${esc(t.Kind)}</div><h2>${esc(t.Name)}</h2>${[['Members',t.Members],['Actual tag pair',t['Actual tag pair']],['Manager',t.Manager],['Status',t.Status],['Note',t.Note]].filter(x=>x[1]).map(([k,v])=>`<div class="detail-row"><h4>${esc(k)}</h4><p>${esc(v)}</p></div>`).join('')}</div>`;openDrawer();setTimeout(()=>{$('[data-edit-team]')?.addEventListener('click',()=>editTeam(id))},0)}
function editTeam(id=null){const t=currentTeams().find(x=>x._id===id)||{_id:uid('team'),Name:'',Brand:'Raw',Kind:'Tag team',Members:'',Manager:'',Status:'Active',Note:''},isBase=BASE.teams.some(x=>x._id===t._id);openModal(`<div class="eyebrow">TEAM / FACTION</div><h2 id="modalTitle">${id?'Edit':'Add'} team</h2><form class="form" id="teamForm"><label>Name<input name="name" value="${esc(t.Name)}" required></label><div class="row"><label>Brand<select name="brand">${['Raw','SmackDown','NXT','Cross-brand'].map(v=>`<option ${t.Brand===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Kind<input name="kind" value="${esc(t.Kind)}"></label></div><label>Members<textarea name="members">${esc(t.Members)}</textarea></label><div class="row"><label>Manager<input name="manager" value="${esc(t.Manager||'')}"></label><label>Status<input name="status" value="${esc(t.Status||'Active')}"></label></div><label>Notes<textarea name="note">${esc(t.Note||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelTeam">Cancel</button><button class="btn primary">Save team</button></div></form>`);$('#cancelTeam').onclick=closeModal;$('#teamForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),changes={Name:f.get('name'),Brand:f.get('brand'),Kind:f.get('kind'),Members:f.get('members'),Manager:f.get('manager'),Status:f.get('status'),Note:f.get('note')};if(isBase)save.teams[t._id]={...(save.teams[t._id]||{}),...changes};else{Object.assign(t,changes);if(!id)save.customTeams.push(t)}persist();log('Team',changes.Name,`${changes.Status} · ${changes.Members}`);closeModal();closeDrawer();toast('Team updated.');render()}}

function returnsView(){const base=BASE.absences.map(currentAbsence),data=(state.returnView==='Absences & Returns'?base:BASE.legends).filter(r=>Object.values(r).join(' ').toLowerCase().includes(state.query.toLowerCase()));return `${pageHead('OUT OF THE WEEKLY ROTATION','Injuries, absences & returns','Starting absences are reference facts; from here you control your Universe availability.')}${tabs(['Absences & Returns','Legends & Guests'],state.returnView,'returnview')}<div class="filters">${searchbox('Search a name or return plan…')}<span class="count">${data.length} entries</span></div><div class="reference-grid">${data.map(r=>state.returnView==='Absences & Returns'?`<article class="info-card" data-absence="${r._id}"><div class="body"><small>${esc(r.Status)}</small><h3>${esc(r.Person)}</h3><p>${esc(r['Proposed Universe return']||r['Established information']||'')}</p><span class="more">Open & update ↗</span></div></article>`:`<article class="info-card"><div class="body"><small>${esc(r.Lane)}</small><h3>${esc(r['Person / group'])}</h3><p>${esc(r['Story application'])}</p></div></article>`).join('')}</div><div class="note">Future return dates are your Universe booking. They are not medical-clearance predictions.</div>`}
function absenceDetail(id){const r=currentAbsence(BASE.absences.find(x=>x._id===id));$('#drawerBody').innerHTML=`<div class="drawer-pad"><div class="drawer-actions"><button class="btn primary" data-edit-absence="${id}">Update status</button></div><div class="eyebrow">${esc(r.Status)}</div><h2>${esc(r.Person)}</h2>${[['Starting information',r['Established information']],['Universe return plan',r['Proposed Universe return']],['Return program',r['Return program']],['Action',r['Immediate action']]].filter(x=>x[1]).map(([k,v])=>`<div class="detail-row"><h4>${esc(k)}</h4><p>${esc(v)}</p></div>`).join('')}</div>`;openDrawer();setTimeout(()=>{$('[data-edit-absence]')?.addEventListener('click',()=>editAbsence(id))},0)}
function editAbsence(id){const base=BASE.absences.find(x=>x._id===id),r=currentAbsence(base);openModal(`<div class="eyebrow">AVAILABILITY UPDATE</div><h2 id="modalTitle">${esc(r.Person)}</h2><form class="form" id="absenceForm"><label>Status<input name="status" value="${esc(r.Status)}"></label><label>Universe return / timing<input name="return" value="${esc(r['Proposed Universe return']||'')}"></label><label>Return program / notes<textarea name="program">${esc(r['Return program']||'')}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancelAbsence">Cancel</button><button class="btn primary">Save status</button></div></form>`);$('#cancelAbsence').onclick=closeModal;$('#absenceForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);save.absences[id]={Status:f.get('status'),'Proposed Universe return':f.get('return'),'Return program':f.get('program')};persist();log('Availability',r.Person,`${f.get('status')} · ${f.get('return')}`);closeModal();closeDrawer();toast('Availability updated.');render()}}

function resultsView(){const results=Object.values(save.results).sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at))),history=save.history;return `${pageHead('YOUR UNIVERSE HISTORY','History & results','A running record of watched matches, title changes, roster moves, injuries, stories, and season updates.',`<button class="btn primary" data-route="shows">Enter this week’s card</button>`)}<div class="result-summary"><div><strong>${results.length}</strong><span>match results</span></div><div><strong>${history.filter(x=>x.type==='Championship').length}</strong><span>title changes / updates</span></div><div><strong>${save.meta.season}</strong><span>season</span></div><div><strong>${save.meta.currentWeek}</strong><span>current week</span></div></div>${history.length?`<div class="timeline-history">${history.map(h=>`<article><div class="history-icon">${h.type==='Result'?'✓':h.type==='Championship'?'♛':h.type==='Story'?'ϟ':'•'}</div><div><small>Season ${h.season} · Week ${h.week} · ${new Date(h.at).toLocaleString()}</small><h3>${esc(h.title)}</h3><p>${esc(h.detail)}</p></div>${pill(h.type)}</article>`).join('')}</div>`:`<div class="empty"><div style="font-size:40px">✓</div><h3>Your Universe history starts here.</h3><p>Add the first game-booked card, watch it, and record the result.</p><button class="btn primary" data-route="shows">Open this week →</button></div>`}`}

function manageView(){const photoCount=Object.keys(save.photos).length,episodeCount=Object.values(save.episodes).filter(x=>x.items?.length).length;return `${pageHead('THIS IS YOUR SAVE','My Universe','Carry this control center through every season. Backup your data before major changes.',`<button class="btn primary" id="exportSave">↓ Export backup</button>`)}<div class="manage-grid"><article class="manage-card"><div class="eyebrow">CURRENT POSITION</div><h2>Season ${String(save.meta.season).padStart(2,'0')}</h2><p>${esc(save.meta.seasonLabel)} · Week ${save.meta.currentWeek}<br/>Week begins ${formatDate(weekDate())}</p><div class="manage-actions"><button class="btn" id="advanceWeek">Advance one week →</button><button class="btn" id="newSeason">Start new season</button></div></article><article class="manage-card"><div class="eyebrow">UNIVERSE DATA</div><h2>${esc(save.meta.name)}</h2><p>${episodeCount} show cards entered · ${Object.keys(save.results).length} results · ${photoCount} custom photos.</p><div class="manage-actions"><button class="btn" id="renameUniverse">Rename</button><button class="btn" id="importSave">↑ Import backup</button></div></article><article class="manage-card danger-zone"><div class="eyebrow">STARTING SNAPSHOT</div><h2>Reset Universe</h2><p>Returns the site to the October 2026 starting state and erases your local edits.</p><button class="btn danger" id="resetSave">Reset to starting snapshot</button></article></div><div class="note"><b>Where your data lives:</b> this version saves in your browser on the device where you use it. Export a JSON backup regularly—especially before clearing browser data, changing devices, or moving to another host.</div>`}
function advanceWeek(){save.meta.currentWeek++;save.meta.currentDate=weekDate();persist();log('Season','Advanced week',`Now Season ${save.meta.season}, Week ${save.meta.currentWeek}.`);toast(`Advanced to Week ${save.meta.currentWeek}.`);render()}
function newSeason(){openModal(`<div class="eyebrow">NEW SEASON</div><h2 id="modalTitle">Start the next season?</h2><p>Champions, roster edits, stories, teams, photos, and history will carry forward. The week counter resets to 1.</p><form class="form" id="seasonForm"><label>Season label<input name="label" value="${new Date().getFullYear()+1} / ${String(new Date().getFullYear()+2).slice(-2)}"></label><label>Season start date<input type="date" name="date" value="${weekDate()}"></label><div class="form-actions"><button type="button" class="btn" id="cancelSeason">Cancel</button><button class="btn primary">Start season ${save.meta.season+1}</button></div></form>`);$('#cancelSeason').onclick=closeModal;$('#seasonForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);save.meta.season++;save.meta.seasonLabel=f.get('label');save.meta.startDate=f.get('date');save.meta.currentWeek=1;save.meta.currentDate=f.get('date');persist();log('Season',`Season ${save.meta.season} begins`,save.meta.seasonLabel);closeModal();toast('New season started.');render()}}
function exportSave(){const blob=new Blob([JSON.stringify({app:'WWE Universe Control Center',exportedAt:new Date().toISOString(),save},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`WWE-Universe-S${save.meta.season}-W${save.meta.currentWeek}-backup.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importSave(){openModal(`<div class="eyebrow">IMPORT BACKUP</div><h2 id="modalTitle">Restore a Universe backup</h2><p>This replaces the current local save. Export your current one first if you want to keep it.</p><form class="form" id="importForm"><label>Backup JSON<input type="file" id="importFile" accept="application/json,.json" required></label><div class="form-actions"><button type="button" class="btn" id="cancelImport">Cancel</button><button class="btn primary">Import backup</button></div></form>`);$('#cancelImport').onclick=closeModal;$('#importForm').onsubmit=e=>{e.preventDefault();const file=$('#importFile').files[0];if(!file)return;const rd=new FileReader();rd.onload=()=>{try{const x=JSON.parse(rd.result),incoming=x.save||x;if(incoming.version!==4)throw Error('Backup version is not compatible.');save=incoming;persist();closeModal();toast('Backup restored.');render()}catch(err){toast(err.message||'Invalid backup file.')}};rd.readAsText(file)}}
function resetSave(){if(!confirm('Erase this website save and return to the October 2026 starting snapshot?'))return;save=blankSave();persist();toast('Starting snapshot restored.');render()}

const setupSheets=['Start Here','Watch Settings','Match Tables','Downloads & DLC','Attire Updates','Booking Rules','Setup Checks','Exclude & Duplicates'];
function setupView(){const data=rows(state.setupView).filter(r=>Object.values(r).join(' ').toLowerCase().includes(state.query.toLowerCase()));const keymap={'Start Here':'Area','Watch Settings':'Area','Match Tables':'Match type','Downloads & DLC':'Person','Attire Updates':'Person / group','Booking Rules':'Rule','Setup Checks':'Check','Exclude & Duplicates':'Entry'},key=keymap[state.setupView];return `${pageHead('REFERENCE, NOT THE LIVE SAVE','Setup reference','The October 2026 starting instructions stay here. Weekly cards and future outcomes do not auto-populate your live Universe.')}${tabs(setupSheets,state.setupView,'setupview')}<div class="filters">${searchbox('Search '+state.setupView.toLowerCase()+'…')}<span class="count">${data.length} entries</span></div><div class="reference-grid">${data.map(r=>{const title=r[key],vals=Object.entries(r).filter(([k,v])=>!['_id',key].includes(k)&&v);return `<article class="info-card" data-detail="${state.setupView}|${r._id}|${key}"><div class="body"><small>${esc(vals[0]?.[1]||state.setupView)}</small><h3>${esc(title)}</h3><p>${esc(vals[1]?.[1]||vals[0]?.[1]||'Open details')}</p><span class="more">Open reference ↗</span></div></article>`}).join('')}</div>${state.setupView==='Attire Updates'?'<div class="note">Presentation rule: neutral renders first. Do not use a picture that visibly shows a championship the wrestler does not currently hold in your save.</div>':''}`}
function creditsView(){return `${pageHead('REFERENCE DESK','Snapshot & image policy','Starting data comes from the September 24, 2026 Universe workbook. Your later edits are your save’s canon.')}<div class="prose"><h2>Pictures</h2><p>The site uses a small set of default reference photos and crops them tightly to head-and-shoulders. If a picture shows an outdated or incorrect championship, replace it from the Superstar profile. Custom uploads are saved in your browser.</p><h2>Starting data</h2><p>Roster, titles, title divisions, relationships, teams, starting story context, absences, and the PLE calendar form the October 2026 baseline. The original preplanned four-week match cards are deliberately not active here.</p><h2>Long-term use</h2><p>The site is meant to follow your Universe for multiple seasons. Use My Universe to advance weeks, start new seasons, export backups, and move the save to another browser or device.</p></div>`}

function detail(r,kicker,titleKey){const title=r[titleKey]||titleKey;$('#drawerBody').innerHTML=`<div class="drawer-pad"><div class="eyebrow">${esc(kicker)}</div><h2>${esc(title)}</h2>${Object.entries(r).filter(([k,v])=>k!=='_id'&&k!==titleKey&&v).map(([k,v])=>`<div class="detail-row"><h4>${esc(k)}</h4>${/^https?:/.test(v)?`<p><a href="${esc(v.split(/[;\s]/)[0])}" target="_blank" rel="noreferrer">View source ↗</a></p>`:`<p>${esc(v)}</p>`}</div>`).join('')}</div>`;openDrawer()}
function openDetailBy(sheet,id,key){const r=rows(sheet).find(x=>x._id===id);if(r)detail(r,sheet.toUpperCase(),key)}
function globalSearch(){openModal(`<div class="eyebrow">UNIVERSE SEARCH</div><h2 id="modalTitle">Find anything fast</h2><label class="searchbox" style="max-width:none;margin-top:18px">⌕<input id="globalQuery" autofocus placeholder="Superstar, title, story, team…"></label><div class="search-results" id="searchResults"><div class="note">Start typing to search your whole Universe.</div></div>`);setTimeout(()=>$('#globalQuery')?.focus(),50);$('#globalQuery').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q)return $('#searchResults').innerHTML='<div class="note">Start typing to search your whole Universe.</div>';const hits=[];rosterNow().filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)).slice(0,12).forEach(r=>hits.push({type:'Superstar',title:r.Name,sub:r['Home brand'],person:r.Name}));BASE.titles.filter(r=>Object.values({...r,...save.titles[r._id]}).join(' ').toLowerCase().includes(q)).slice(0,8).forEach(r=>hits.push({type:'Championship',title:r.Championship,sub:currentChampion(r),titleId:r._id}));currentStories().filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)).slice(0,8).forEach(r=>hits.push({type:'Story',title:r.Program,sub:r.Show,story:r._id}));currentTeams().filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)).slice(0,6).forEach(r=>hits.push({type:'Team',title:r.Name,sub:r.Brand,team:r._id}));$('#searchResults').innerHTML=hits.length?hits.map((h,i)=>`<div class="search-hit" data-hit="${i}"><div><b>${esc(h.title)}</b><small style="display:block">${esc(h.type)} · ${esc(h.sub||'')}</small></div><span>↗</span></div>`).join(''):'<div class="empty"><h3>No matches found</h3></div>';$$('[data-hit]').forEach(el=>el.onclick=()=>{const h=hits[+el.dataset.hit];closeModal();h.person?person(h.person):h.titleId?titleDetail(h.titleId):h.story?storyDetail(h.story):h.team?teamDetail(h.team):null})}}

function bindView(){
 $$('[data-route]').forEach(x=>x.onclick=()=>route(x.dataset.route));
 $$('[data-person]').forEach(x=>x.onclick=()=>person(x.dataset.person));
 $$('[data-title]').forEach(x=>x.onclick=()=>titleDetail(x.dataset.title));
 $$('[data-change-title]').forEach(x=>x.onclick=e=>{e.stopPropagation();changeChampion(x.dataset.changeTitle)});
 $$('[data-story]').forEach(x=>x.onclick=()=>storyDetail(x.dataset.story));
 $$('[data-team]').forEach(x=>x.onclick=()=>teamDetail(x.dataset.team));
 $$('[data-absence]').forEach(x=>x.onclick=()=>absenceDetail(x.dataset.absence));
 $$('[data-brand]').forEach(x=>x.onclick=()=>{state.brand=x.dataset.brand;render()});
 $$('[data-teamview]').forEach(x=>x.onclick=()=>{state.teamView=x.dataset.teamview;state.query='';render()});
 $$('[data-returnview]').forEach(x=>x.onclick=()=>{state.returnView=x.dataset.returnview;state.query='';render()});
 $$('[data-setupview]').forEach(x=>x.onclick=()=>{state.setupView=x.dataset.setupview;state.query='';render()});
 $$('[data-show]').forEach(x=>x.onclick=()=>{state.show=x.dataset.show;render()});
 $$('[data-showlink]').forEach(x=>x.onclick=()=>{state.route='shows';state.show=x.dataset.showlink;location.hash='shows';render()});
 $$('[data-record-live]').forEach(x=>x.onclick=()=>recordLiveResult(x.dataset.recordLive));
 $$('[data-edit-item]').forEach(x=>x.onclick=()=>{const ep=save.episodes[weekKey(state.show)],m=ep?.items.find(y=>y.id===x.dataset.editItem);if(m)addCardItem(m.type,m)});
 $$('[data-edit-ple]').forEach(x=>x.onclick=()=>editPLE(x.dataset.editPle));
 $$('[data-detail]').forEach(x=>x.onclick=()=>{const [s,id,k]=x.dataset.detail.split('|');openDetailBy(s,id,k)});
 const fq=$('#filterQuery');if(fq)fq.oninput=e=>{state.query=e.target.value;render()};
 const sv=$('#storyView');if(sv)sv.onchange=e=>{state.storyView=e.target.value;render()};
 $('#addSuperstar')?.addEventListener('click',addSuperstar);$('#addStory')?.addEventListener('click',addStory);$('#addTeam')?.addEventListener('click',()=>editTeam());$('#addPLE')?.addEventListener('click',()=>editPLE());
 $('#addMatch')?.addEventListener('click',()=>addCardItem('match'));$('#emptyAddMatch')?.addEventListener('click',()=>addCardItem('match'));$('#addSegment')?.addEventListener('click',()=>addCardItem('segment'));
 $('#prevWeek')?.addEventListener('click',()=>{if(save.meta.currentWeek>1){save.meta.currentWeek--;persist();render()}});$('#nextWeek')?.addEventListener('click',()=>{save.meta.currentWeek++;persist();render()});
 $('#copyCard')?.addEventListener('click',async()=>{const ep=save.episodes[weekKey(state.show)]||{items:[]};const txt=`${state.show} · Season ${save.meta.season} Week ${save.meta.currentWeek}\n`+ep.items.map((x,i)=>`${i+1}. ${x.text}${x.stakes?' — '+x.stakes:''}`).join('\n');try{await navigator.clipboard.writeText(txt);toast('Card copied.')}catch{openModal(`<h2 id="modalTitle">Card text</h2><textarea style="width:100%;min-height:260px">${esc(txt)}</textarea>`)}});
 $('#advanceWeek')?.addEventListener('click',advanceWeek);$('#newSeason')?.addEventListener('click',newSeason);$('#exportSave')?.addEventListener('click',exportSave);$('#importSave')?.addEventListener('click',importSave);$('#resetSave')?.addEventListener('click',resetSave);
 $('#renameUniverse')?.addEventListener('click',()=>{const n=prompt('Universe name',save.meta.name);if(n?.trim()){save.meta.name=n.trim();persist();render()}});
}

const views={overview,shows:showsView,roster:rosterView,champions,stories:storiesView,calendar:calendarView,teams:teamsView,returns:returnsView,results:resultsView,manage:manageView,setup:setupView,credits:creditsView};
$('#menuBtn').onclick=openSidebar;$('#scrim').onclick=()=>{closeDrawer();closeSidebar()};$('#drawerClose').onclick=closeDrawer;$('#modalClose').onclick=closeModal;$('#modalWrap').onclick=e=>{if(e.target===$('#modalWrap'))closeModal()};$('#searchBtn').onclick=globalSearch;window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch()}if(e.key==='Escape'){closeModal();closeDrawer();closeSidebar()}});window.addEventListener('hashchange',()=>{state.route=(location.hash.slice(1)||'overview').split('?')[0];render()});
navRender();render();
})();
